    public void compute() {
        FortressTaskRunner.setCurrentTask(this);
        try {
            Environment inner = eval.e.extendAt(expr);
            Evaluator e = new Evaluator(inner);
            res = expr.accept(e);
        }
        catch (NullPointerException e) {
            throw e;
        }
        catch (Exception e) {
            recordException(e);
        }
        finally {
            /* Null out fields so they are not retained by GC after termination. */
            eval = null;
            expr = null;
            transaction = null;
        }
    }

